package com.salarygrows.live;
import android.app.*;import android.app.WallpaperManager;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import java.text.NumberFormat;import java.util.*;import java.time.*;
public class MainActivity extends Activity {
 final int bg=0xFFF5F4F0,ink=0xFF192623,muted=0xFF75817B,green=0xFF267A58;
 LinearLayout root,content; TextView live,progressText,dayText; ProgressBar bar; Handler handler=new Handler(Looper.getMainLooper()); android.content.SharedPreferences prefs;
 NumberFormat nf=NumberFormat.getNumberInstance(Locale.KOREA);
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String t,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(Typeface.create("sans-serif-medium",Typeface.BOLD));return v;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void add(LinearLayout l,View v,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(top);l.addView(v,p);}
 LinearLayout card(){LinearLayout l=column();l.setBackground(shape(Color.WHITE,22));pad(l,22,21,22,22);return l;}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("salary",MODE_PRIVATE);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);build();}
 void build(){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);root=column();root.setBackgroundColor(bg);pad(root,22,30,22,40);sc.addView(root);setContentView(sc);
 TextView brand=text("MMF",32,ink,true);add(root,brand,0);TextView subtitle=text("MY MONEY FLOW   /   PERSONAL DASHBOARD",10,muted,false);add(root,subtitle,2);
 LinearLayout hero=card();add(root,hero,28);add(hero,text("CURRENT FLOW",12,muted,true),0);live=text("₩ 0",33,ink,true);add(hero,live,18);add(hero,text("매초 갱신되는 나의 수입",12,muted,false),8);
 LinearLayout pay=card();add(root,pay,14);add(pay,text("NEXT PAYDAY",12,muted,true),0);dayText=text("",26,ink,true);add(pay,dayText,10);bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(green));add(pay,bar,16);progressText=text("",12,muted,false);add(pay,progressText,9);
 LinearLayout settings=card();add(root,settings,14);add(settings,text("설정",19,ink,true),0);
 EditText monthly=new EditText(this);monthly.setSingleLine(true);monthly.setInputType(2);monthly.setText(String.valueOf(prefs.getLong("monthly",2900000)));monthly.setHint("월급 (원)");add(settings,text("월급 (원)",12,muted,false),17);add(settings,monthly,2);
 EditText day=new EditText(this);day.setSingleLine(true);day.setInputType(2);day.setText(String.valueOf(prefs.getInt("day",15)));add(settings,text("급여일 (1~31)",12,muted,false),14);add(settings,day,2);
 SeekBar x=seek(settings,"가로 위치",prefs.getInt("x",50),0,100);SeekBar y=seek(settings,"세로 위치",prefs.getInt("y",46),0,100);SeekBar size=seek(settings,"숫자 크기",prefs.getInt("size",100),50,200);
 Button save=button("설정 저장",green);add(settings,save,18);save.setOnClickListener(v->{try{long m=Long.parseLong(monthly.getText().toString().trim());int d=Integer.parseInt(day.getText().toString().trim());if(m<=0||m>100000000000L||d<1||d>31)throw new Exception();prefs.edit().putLong("monthly",m).putInt("day",d).putInt("x",x.getProgress()).putInt("y",y.getProgress()).putInt("size",size.getProgress()+50).apply();Toast.makeText(this,"설정 저장 완료",Toast.LENGTH_SHORT).show();refresh();}catch(Exception e){Toast.makeText(this,"월급과 급여일을 확인하세요",Toast.LENGTH_LONG).show();}});
 Button wallpaper=button("라이브 배경화면 적용",ink);add(settings,wallpaper,10);wallpaper.setOnClickListener(v->{Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,SalaryWallpaperService.class));try{startActivity(i);}catch(Exception e){startActivity(new Intent(WallpaperManager.ACTION_LIVE_WALLPAPER_CHOOSER));}});
 LinearLayout receipt=card();add(root,receipt,14);add(receipt,text("월급 수령",19,ink,true),0);add(receipt,text("수령 버튼은 축하 효과만 표시하며 급여 계산 기준은 변경하지 않습니다.",12,muted,false),7);Button received=button("월급 받았어요",green);add(receipt,received,14);received.setOnClickListener(v->celebrate());
 LinearLayout friends=card();add(root,friends,14);add(friends,text("FRIENDS & CHAT",17,ink,true),0);add(friends,text("급여액과 급여일은 친구에게 공개하지 않습니다.",12,muted,false),8);add(friends,text("친구 추가와 1:1 채팅은 계정·서버 연결이 필요한 다음 개발 단계입니다. 현재 버전에서는 사용할 수 없습니다.",13,ink,false),12);
 refresh();}
 SeekBar seek(LinearLayout l,String label,int initial,int min,int max){add(l,text(label,12,muted,false),16);SeekBar s=new SeekBar(this);s.setMax(max-min);s.setProgress(Math.max(0,Math.min(max-min,initial-min)));s.setTag(min);add(l,s,3);return s;}
 Button button(String title,int color){Button b=new Button(this);b.setText(title);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(shape(color,14));return b;}
 void refresh(){if(live==null)return;long now=System.currentTimeMillis();long m=prefs.getLong("monthly",2900000);int d=prefs.getInt("day",15);double[] v=SalaryMath.calculate(m,d,now);live.setText("₩ "+nf.format((long)v[0]));LocalDate today=LocalDate.now();LocalDate target=today.withDayOfMonth(Math.min(d,today.lengthOfMonth()));if(!target.isAfter(today)){YearMonth next=YearMonth.from(today).plusMonths(1);target=next.atDay(Math.min(d,next.lengthOfMonth()));}long remaining=java.time.temporal.ChronoUnit.DAYS.between(today,target);dayText.setText("D-"+remaining);int percent=(int)Math.max(0,Math.min(1000,v[0]/m*1000));bar.setProgress(percent);progressText.setText(String.format(Locale.KOREA,"급여 주기 진행률 %.1f%%",percent/10.0));}
 Runnable update=new Runnable(){public void run(){refresh();handler.postDelayed(this,1000-System.currentTimeMillis()%1000);}};
 @Override protected void onResume(){super.onResume();handler.removeCallbacks(update);handler.post(update);}
 @Override protected void onPause(){handler.removeCallbacks(update);super.onPause();}
 void celebrate(){final Dialog dialog=new Dialog(this);LinearLayout box=column();box.setGravity(Gravity.CENTER);box.setBackground(shape(0xFF172A23,24));pad(box,30,42,30,38);TextView stars=text("✦  ✧  ✦  ✧  ✦",28,0xFFD8BC75,true);stars.setGravity(Gravity.CENTER);add(box,stars,0);TextView title=text("축하합니다!",29,Color.WHITE,true);title.setGravity(Gravity.CENTER);add(box,title,22);TextView caption=text("이번 달도 수고 많았어요.",15,0xFFD6E4DB,false);caption.setGravity(Gravity.CENTER);add(box,caption,12);Button close=button("확인",green);add(box,close,24);close.setOnClickListener(v->dialog.dismiss());dialog.setContentView(box);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(getResources().getDisplayMetrics().widthPixels-dp(42),-2);}dialog.show();w=dialog.getWindow();if(w!=null)w.setLayout(getResources().getDisplayMetrics().widthPixels-dp(42),-2);stars.animate().rotationBy(20).scaleX(1.15f).scaleY(1.15f).setDuration(400).withEndAction(()->stars.animate().rotation(0).scaleX(1).scaleY(1).setDuration(400).start()).start();}
}
